const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(ICONS[name]||ICONS.FileText).map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).map(([k,v])=>`${k}="${esc(v)}"`).join(' ')} />`).join('')}</svg>`}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(e=>{e.innerHTML=icon(e.dataset.icon);e.removeAttribute('data-icon')})}
const clone=x=>JSON.parse(JSON.stringify(x));
const KEY='mint-preset-prototype-v1';
const seeds=[
 ['init','变量初始化','基础结构','{{setvar::worldview::}}\n{{setvar::narration::}}\n{{setvar::identity::}}\n{{trim}}'],
 ['identity','小西瓜 · 身份定义','基础结构','你是小西瓜，一位耐心的故事创作助手。\n用温和、清楚的语言协助用户推进故事。\n创作前检查角色动机、视角与情节衔接。'],
 ['main','主要提示','基础结构','根据角色设定和当前情境续写故事。\n尊重用户已经给出的行动，不代替用户作出选择。'],
 ['persona','玩家描述','角色与上下文','{{persona}}'],
 ['char','角色描述','角色与上下文','{{description}}'],
 ['world','世界书','角色与上下文','{{world_info}}'],
 ['history','聊天记录','角色与上下文','{{chat_history}}'],
 ['view','世界观 · 现代日常','世界与叙事','{{setvar::worldview::\n<worldview>\n以现代城市日常为背景，遵循现实社会中的信息、交通和职业边界。\n</worldview>\n}}\n{{trim}}'],
 ['pov','第三人称 · 限知','世界与叙事','使用第三人称。角色只能知道自己能够观察或推断的信息。'],
 ['pace','叙事节奏','世界与叙事','允许普通生活里的停顿，让情节根据角色行动自然发展。'],
 ['dialogue','对白与动作','世界与叙事','对白保持自然，动作服务于此刻的情境。'],
 ['cast','群像与支线','世界与叙事','配角拥有自己的目标，支线与主线有可追踪的联系。'],
 ['boundary','用户行动边界','写作约束','不替用户补充尚未表达的心理、决定或动作。'],
 ['continuity','情节衔接','写作约束','承接上一轮尚未完成的动作和事件，保留未解决的线索。'],
 ['length','正文篇幅','写作约束','正文约 800 至 1200 字，按照场景需要调整。'],
 ['output','输出格式','输出与附加','{{getvar::worldview}}\n<content>\n正文\n</content>'],
 ['summary','本轮摘要','输出与附加','<recap>新增事实、状态变化与未解决线索。</recap>'],
 ['choice','行动选项','输出与附加','在正文后提供三个方向不同的行动选项。']
].map(([id,name,group,content],i)=>({id,name,group,content,enabled:i!==11&&i!==17,role:'system',depth:4,position:'relative'}));
const presets=[{id:'daily',name:'日常创作',meta:'我的预设',color:'#e0eee5',ink:'#5f9074',type:'rings'},{id:'wasteland',name:'末日漫游',meta:'世界观参考',color:'#e9e6dc',ink:'#9a9072',type:'sun'},{id:'abo',name:'ABO 设定',meta:'世界观参考',color:'#eee6ed',ink:'#a28aa0',type:'orbit'},{id:'ancient',name:'古风叙事',meta:'写作参考',color:'#e3e9ee',ink:'#7b92a4',type:'stairs'},{id:'simple',name:'极简写作',meta:'基础结构',color:'#efece3',ink:'#a79770',type:'lines'},{id:'ensemble',name:'群像剧场',meta:'叙事参考',color:'#e5e9e1',ink:'#8a9b7a',type:'dots'}];
let state={entries:clone(seeds),baseline:clone(seeds),refs:['wasteland','abo'],messages:[],plans:[],target:'daily',knowledgeOn:[true,true,false],collapsed:[],lastSaved:null};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.entries)&&saved.entries.every(e=>e&&typeof e.id==='string'&&typeof e.content==='string'))state={...state,...saved}}catch{}
let route=location.hash.slice(1)||'library',tab='edit',entryId=null,search='',filter='all',bulk=false,selected=new Set(),planSelection=new Set(state.plans.map((_,i)=>i)),toastTimer,history=[];
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('浏览器存储不可用，本次修改仅在页面中保留')}};
const changes=()=>[...state.entries.filter((e,i)=>JSON.stringify(e)!==JSON.stringify(state.baseline.find(b=>b.id===e.id))||state.baseline.findIndex(b=>b.id===e.id)!==i),...state.baseline.filter(b=>!state.entries.some(e=>e.id===b.id)).map(b=>({...b,content:'',_removed:true}))];
const dirty=()=>changes().length;
function changeNote(e){if(e._removed)return '移出草稿';const b=state.baseline.find(x=>x.id===e.id);if(!b)return '新增条目';const labels=[];const from=state.baseline.findIndex(x=>x.id===e.id),to=state.entries.findIndex(x=>x.id===e.id);if(from!==to)labels.push(`顺序 ${from+1} → ${to+1}`);if(b.enabled!==e.enabled)labels.push(e.enabled?'已启用':'已停用');if(b.role!==e.role)labels.push(`Role ${b.role} → ${e.role}`);if(b.depth!==e.depth)labels.push(`深度 ${b.depth} → ${e.depth}`);if(b.position!==e.position)labels.push('注入位置已修改');if(b.group!==e.group)labels.push(`分组 ${e.group}`);return labels.join(' · ')||'内容修改'}
const checkpoint=()=>{history.push(clone(state));if(history.length>20)history.shift()};
function toast(s){clearTimeout(toastTimer);const e=document.getElementById('toast');e.textContent=s;e.classList.add('show');toastTimer=setTimeout(()=>e.classList.remove('show'),2900)}
function cover(p){const s=p.ink;let v='';if(p.type==='rings')v=`<circle cx="37" cy="37" r="27"/><circle cx="71" cy="37" r="27"/><path d="M15 58h80"/>`;if(p.type==='sun')v=`<circle cx="57" cy="29" r="17"/><path d="M8 57 35 32l25 29 17-17 25 18M8 68h94"/>`;if(p.type==='orbit')v=`<ellipse cx="57" cy="37" rx="43" ry="17" transform="rotate(-30 57 37)"/><ellipse cx="57" cy="37" rx="43" ry="17" transform="rotate(30 57 37)"/><circle cx="57" cy="37" r="5" fill="${s}"/>`;if(p.type==='stairs')v=`<path d="M15 64V48h20V32h20V16h37M35 64V48h20V32h37M55 64V48h37"/>`;if(p.type==='lines')v=`<path d="M17 17h78M17 31h62M17 45h78M17 59h43"/>`;if(p.type==='dots')v=[23,53,83].map((x,i)=>`<circle cx="${x}" cy="${35+i%2*13}" r="12"/><path d="M${x} ${50+i%2*13}v12"/>`).join('');return `<svg viewBox="0 0 114 80" fill="none" stroke="${s}" stroke-width="1.4">${v}</svg>`}
function renderNav(){document.getElementById('nav').innerHTML=[['library','Library','预设库'],['work','PanelsTopLeft','工作区'],['lab','FlaskConical','实验室'],['knowledge','BookOpen','经验库']].map(([id,ic,n])=>`<button data-action="nav" data-value="${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ic)}<span>${n}</span>${id==='work'&&(dirty()+state.plans.length)?`<span class="badge">${dirty()+state.plans.length}</span>`:''}</button>`).join('')+'<div class="nav-foot">为你的故事<br>整理一点秩序。</div>'}
function render(){if(!['library','work','lab','knowledge'].includes(route))route='library';renderNav();document.getElementById('main').innerHTML=`<div class="content fade">${route==='library'?library():route==='work'?workspace():route==='lab'?lab():knowledge()}</div>`;hydrateIcons()}
function nav(v){if(entryId)entryId=null;route=v;search='';location.hash=v;render();window.scrollTo(0,0)}
function library(){let list=presets.filter(p=>(filter==='all'||(filter==='mine'?p.id===state.target:(state.refs.includes(p.id)||(state.refEntries||[]).some(r=>r.presetId===p.id))))&&p.name.includes(search));return `<div class="page-heading"><div><h1>我的预设</h1><p class="muted">把喜欢的规则，整理成自己的创作方式。</p></div><button class="btn primary" data-action="new">${icon('Plus')}新建</button></div><div class="library-toolbar"><label class="search">${icon('Search')}<input id="library-search" aria-label="搜索预设" placeholder="搜索预设" value="${esc(search)}"></label><button class="btn" data-action="import">${icon('Download')}导入</button></div><div class="segmented" aria-label="预设筛选">${[['all','全部'],['mine','正在编辑'],['refs','参考预设']].map(([id,n])=>`<button data-action="filter" data-value="${id}" class="${filter===id?'active':''}">${n}${id==='refs'?`<span class="badge">${state.refs.length}</span>`:''}</button>`).join('')}</div><div class="preset-grid">${list.map(p=>`<article class="preset ${p.id===state.target?'current':''}"><div class="preset-cover" style="--cover:${p.color};--cover-text:${p.ink}">${cover(p)}<span class="cover-label">${p.id===state.target?'正在编辑':'预设素材'}</span></div><div class="preset-body"><button class="preset-name" data-action="open-preset" data-id="${p.id}">${p.id===state.target?esc(state.targetName||p.name):p.name}</button><div class="preset-meta">${p.meta} <span aria-hidden="true"> / </span> ${p.id===state.target?state.entries.length:'18'} 个条目</div><div class="preset-footer"><button class="btn ${p.id===state.target?'soft':''}" data-action="open-preset" data-id="${p.id}">${p.id===state.target?'继续编辑':'查看条目'}${icon('ArrowUpRight')}</button><button class="text-button" data-action="toggle-ref" data-id="${p.id}" aria-label="${state.refs.includes(p.id)?'移除参考':'加入参考'} ${p.name}">${icon(state.refs.includes(p.id)?'Check':'Plus')}${state.refs.includes(p.id)?'已参考':'参考'}</button></div></div></article>`).join('')}</div>${!list.length?'<div class="empty">没有找到对应预设</div>':''}<div class="notice">${icon('CircleHelp')}<span>选择一份目标预设开始编辑，也可以先把喜欢的预设加入参考。</span></div>`}
function refStrip(){return `<div class="reference-strip"><span>参考</span>${state.refs.map(id=>{const p=presets.find(p=>p.id===id);return `<button data-action="references">${icon('FileText')}${esc(p?.name||id)}</button>`}).join('')}<button data-action="references" aria-label="选择参考预设">${icon('Plus')}选择</button></div>`}
function workspace(){if(entryId)return entryEditor();return `<div class="workspace-heading"><div class="grow"><h1>${esc(state.targetName||presets.find(p=>p.id===state.target)?.name||'日常创作')}</h1><div class="workspace-subline"><span>我的预设</span><span>/</span><span>${dirty()?`${dirty()} 处草稿修改`:'草稿已保存到浏览器'}</span></div></div><button class="btn" data-action="references">${icon('Layers')}参考 <span class="selection-count">${state.refs.length}</span></button></div><div class="segmented" aria-label="工作区视图">${[['edit','编辑'],['ai','AI 会话'],['review','修改审阅']].map(([id,n])=>`<button data-action="tab" data-value="${id}" class="${tab===id?'active':''}">${n}${id==='review'&&(dirty()+state.plans.length)?`<span class="badge">${dirty()+state.plans.length}</span>`:''}</button>`).join('')}</div>${tab==='edit'?editList():tab==='ai'?chat():review()}`}
function editList(){let list=state.entries.filter(e=>e.name.includes(search)||e.content.includes(search));const groups=[...new Set(list.map(e=>e.group))];return `<div class="work-layout"><section><div class="editor-toolbar"><label class="search">${icon('Search')}<input id="entry-search" placeholder="搜索条目或内容" aria-label="搜索条目或内容" value="${esc(search)}"></label><button class="btn ${bulk?'soft':''}" data-action="bulk">${icon('CheckCheck')}${bulk?'退出多选':'多选'}</button><button class="icon-button" data-action="add-entry" aria-label="新建条目">${icon('Plus')}</button></div>${bulk?`<div class="bulkbar"><span class="grow">已选 ${selected.size} 项</span><button class="btn small" data-action="select-all">全选</button><button class="btn small" data-action="move" ${!selected.size?'disabled':''}>${icon('Move')}移动</button><button class="btn small" data-action="batch-toggle" ${!selected.size?'disabled':''}>启停</button></div>`:''}${groups.map(g=>`<div class="group"><button class="group-title" data-action="collapse" data-value="${esc(g)}" aria-expanded="${!state.collapsed.includes(g)}">${icon(state.collapsed.includes(g)?'ChevronRight':'ChevronDown')}<span>${esc(g)}</span><span class="count">${list.filter(e=>e.group===g).length}</span></button>${!state.collapsed.includes(g)?`<div class="prompt-list">${list.filter(e=>e.group===g).map(e=>{const changed=JSON.stringify(e)!==JSON.stringify(state.baseline.find(b=>b.id===e.id));return `<div class="prompt-row ${changed?'changed':''} ${!e.enabled?'off':''}">${bulk?`<input class="check" type="checkbox" aria-label="选择 ${esc(e.name)}" data-select="${esc(e.id)}" ${selected.has(e.id)?'checked':''}>`:`<span class="grip" aria-hidden="true">${icon('GripVertical')}</span>`}<button class="prompt-open" data-action="edit-entry" data-id="${e.id}"><span class="prompt-name">${changed?'<i class="changed-dot" aria-label="已修改"></i>':''}${esc(e.name)}</span><div class="prompt-note">${['persona','char','world','history'].includes(e.id)?'上下文占位':`${e.content.length} 字符`}</div></button><button class="toggle ${e.enabled?'on':''}" data-action="toggle-entry" data-id="${e.id}" role="switch" aria-checked="${e.enabled}" aria-label="启用 ${esc(e.name)}"></button></div>`}).join('')}</div>`:''}</div>`).join('')}${!list.length?'<div class="empty">没有找到对应条目</div>':''}<div class="sticky-actions"><button class="text-button" data-action="undo" ${!history.length?'disabled':''}>${icon('Undo2')}撤销</button><button class="btn soft" data-action="tab" data-value="ai">${icon('MessageSquare')}让 AI 帮我修改</button></div></section><aside class="outline-panel"><h3>这份预设</h3><div class="outline-item"><span>全部条目</span><span>${state.entries.length}</span></div><div class="outline-item"><span>已启用</span><span>${state.entries.filter(e=>e.enabled).length}</span></div><div class="outline-item"><span>草稿修改</span><span>${dirty()}</span></div><div class="outline-rule"></div><h3>参考内容</h3>${state.refs.map(id=>`<div class="outline-item">${icon('FileText')}<span>${esc(presets.find(p=>p.id===id)?.name)}</span></div>`).join('')}<button class="text-button" data-action="references">更换参考 ${icon('ChevronRight')}</button><div class="outline-rule"></div><p>编辑先留在草稿中。<br>完成后，到修改审阅里统一确认。</p></aside></div>`}
function entryEditor(){const e=state.entries.find(e=>e.id===entryId);if(!e){entryId=null;return workspace()}return `<div class="row spread"><button class="text-button" data-action="back-editor">${icon('ArrowLeft')}返回条目</button><span class="muted">${esc(e.group)}</span></div><input class="editor-title" id="edit-name" aria-label="条目名称" value="${esc(e.name)}"><label class="field-label" for="edit-content">条目内容</label><textarea class="editor-text" id="edit-content" spellcheck="false">${esc(e.content)}</textarea><details class="settings-detail"><summary>发送设置</summary><div class="settings-body"><div class="fields"><label class="field"><span class="field-label">消息角色</span><select id="edit-role">${['system','user','assistant'].map(r=>`<option ${e.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label class="field"><span class="field-label">插入位置</span><select id="edit-position"><option value="relative" ${e.position==='relative'?'selected':''}>相对位置</option><option value="in_chat" ${e.position==='in_chat'?'selected':''}>聊天中</option></select></label><label class="field"><span class="field-label">深度</span><input id="edit-depth" type="number" min="0" max="999" value="${e.depth}"></label><label class="field"><span class="field-label">分组</span><select id="edit-group">${[...new Set(state.entries.map(x=>x.group))].map(g=>`<option ${g===e.group?'selected':''}>${esc(g)}</option>`).join('')}</select></label></div></div></details><div class="sticky-actions"><button class="btn" data-action="reference-entry" data-id="${e.id}">${icon('MessageSquare')}交给 AI 修改</button><button class="btn primary" data-action="save-entry">保存到草稿</button></div>`}
function chat(){return `<div class="chat-wrap">${refStrip()}<div class="chat-headline"><h2>${state.messages.length?'继续打磨你的预设':'你想怎样改这份预设？'}</h2>${!state.messages.length?`<p class="chat-intro">从参考条目创作，或对当前预设做一次整体调整。</p><div class="starter"><button data-action="quick-prompt" data-value="参考末日和 ABO 的条目格式，生成一个古代世界观，并推荐插入位置。">生成古代世界观 ${icon('ArrowUpRight')}</button><button data-action="quick-prompt" data-value="把小西瓜改成大鲸鱼，连同身份、表达方式和创作规划一起修改。">把小西瓜改成大鲸鱼 ${icon('ArrowUpRight')}</button></div>`:''}</div><div class="chat-thread">${state.messages.map(m=>`<div class="message ${m.role==='user'?'user':''}">${m.role==='assistant'?`<div class="avatar">${icon('Layers')}</div>`:''}<div class="message-content">${esc(m.content)}</div></div>`).join('')}${state.plans.length?`<div class="proposal-card"><div class="row spread"><h3>修改建议已整理</h3><span class="pill">${state.plans.length} 处待确认</span></div><p class="muted">逐项查看内容、变量引用和推荐位置。</p><button class="btn soft" data-action="tab" data-value="review">${icon('GitCompareArrows')}查看修改差异</button></div>`:''}</div><form class="composer" id="chat-form"><textarea id="chat-input" aria-label="向 AI 提出修改要求" placeholder="描述你的想法，或继续提出修改意见…" rows="2"></textarea><div class="composer-bottom"><button type="button" class="composer-ref" data-action="references">${icon('Link2')}参考 ${state.refs.length} 份预设</button><button class="send" type="submit" aria-label="发送演示请求">${icon('ArrowUp')}</button></div></form><p class="chat-demo-note">演示交互流程，暂未连接模型。</p></div>`}
function review(){const diffs=changes();return `<div class="review-summary"><div><h2>${state.plans.length?`${state.plans.length} 处建议，等你确认`:dirty()?`${dirty()} 处草稿修改`:'每一次修改，都由你决定'}</h2><p class="muted">${state.plans.length?'接受后加入草稿，原版本保持不变。':dirty()?'检查完成后，保存为新的演示版本。':'修改条目或提出 AI 要求后，在这里比较。'}</p></div>${state.plans.length?`<button class="btn primary" data-action="apply-plans" ${!planSelection.size?'disabled':''}>加入草稿${icon('Check')}</button>`:dirty()?'<button class="btn primary" data-action="save-version">保存演示版本</button>':''}</div>${state.plans.length?state.plans.map((p,i)=>diffCard(p,i,true)).join(''):diffs.length?diffs.map(e=>diffCard({id:e.id,name:e.name,before:state.baseline.find(b=>b.id===e.id)?.content||'',after:e.content,note:changeNote(e)},0,false)).join(''):`<div class="empty"><div class="empty-icon">${icon('GitCompareArrows')}</div><h2>还没有待审阅的修改</h2><p>先编辑一个条目，或让 AI 提出方案。</p><button class="btn soft" data-action="tab" data-value="ai">打开 AI 会话</button></div>`}${state.plans.length?'<div class="review-actions"><button class="btn" data-action="discard-plans">放弃这些建议</button><button class="btn" data-action="tab" data-value="ai">继续对话修改</button></div>':dirty()?'<div class="review-actions"><button class="btn danger" data-action="revert">恢复已保存版本</button></div>':''}<div class="notice">${icon('CircleHelp')}<span>原型只更新浏览器里的演示版本，不会写入酒馆。</span></div>`}
function diffCard(p,i,selectable){return `<article class="diff-card"><div class="diff-title">${selectable?`<input class="check" type="checkbox" aria-label="接受 ${esc(p.name)}" data-plan="${i}" ${planSelection.has(i)?'checked':''}>`:icon('FileText')}<h3>${esc(p.name)}</h3><span>${esc(p.note||'内容修改')}</span></div>${p.before?`<div class="diff-block before"><span class="diff-label">原内容</span>${esc(p.before)}</div>`:''}<div class="diff-block after"><span class="diff-label">${p.note==='移出草稿'?'移出草稿':p.before?'修改后':'新增内容'}</span>${esc(p.after)}</div></article>`}
function lab(){return `<div class="page-heading"><div><h1>实验室</h1><p class="muted">用同一场景，看看修改带来了什么。</p></div><button class="btn" data-action="upgrade">${icon('GitCompareArrows')}预设升级</button></div><div class="lab-grid"><section class="panel"><h3>对照实验</h3><div class="fields"><label class="field"><span class="field-label">原版本</span><select><option>日常创作 · 已保存版</option></select></label><label class="field"><span class="field-label">对比版本</span><select><option>当前草稿</option></select></label></div><label class="field"><span class="field-label">固定场景</span><textarea id="test-scene" style="width:100%;min-height:108px">雨夜，一位旅人在城门关闭前抵达。守城人问起她的来处。</textarea></label><button class="btn primary full" data-action="run-test">${icon('FlaskConical')}查看演示对比</button><div id="test-result"></div></section><aside class="panel"><h3>检查项目</h3>${[['变量展开','核对写入与读取'],['发送顺序','查看 Role 与注入位置'],['输出格式','核对正文与附加内容'],['角色一致性','对照身份与表达方式']].map(([a,b])=>`<div class="metric"><span>${a}</span><span class="muted">${b}</span></div>`).join('')}<div class="small-spacer"></div><p class="muted">正式版本在连接酒馆后读取实际请求。本页展示实验界面的操作方式。</p></aside></div>`}
function knowledge(){const cards=[['具体模型版本','先记录版本，再记录经验','同一模型升级后，保留原有观察，并将相关经验标记为待复测。','通用 · 手动维护'],['变量迁移','把初始化和读取位置一起检查','移植写入变量的条目时，需要确认目标预设存在对应的读取入口，且不会被后续初始化清空。','结构分析 · 源码规则'],['写作观察','较长规则可按任务载入','这是一条待验证的示例经验。可以保留记录，并在实验室固定场景后进行对比。','示例模型 v1 · 待复测']];return `<div class="page-heading"><div><h1>经验库</h1><p class="muted">只在需要时，把合适的经验交给 AI。</p></div><button class="btn" data-action="new-knowledge">${icon('Plus')}添加</button></div><div class="library-toolbar"><label class="search">${icon('Search')}<input id="knowledge-search" placeholder="搜索经验、模型或来源" aria-label="搜索经验" value="${esc(search)}"></label></div><div class="knowledge-list">${cards.map((c,i)=>({c,i})).filter(({c})=>c.join(' ').includes(search)).map(({c,i})=>`<article class="knowledge"><div class="row spread"><span class="pill ${i===2?'warm':''}">${c[0]}</span><button class="toggle ${state.knowledgeOn[i]?'on':''}" role="switch" aria-checked="${state.knowledgeOn[i]}" aria-label="使用经验 ${c[1]}" data-action="knowledge-toggle" data-index="${i}"></button></div><h3 style="margin-top:14px">${c[1]}</h3><p>${c[2]}</p><div class="knowledge-meta">${icon('BookOpen')}<span>${c[3]}</span><span style="margin-left:auto">${state.knowledgeOn[i]?'按需载入':'已停用'}</span></div></article>`).join('')}</div>`}
function modal(title,body,footer=''){const m=document.getElementById('modal');m.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭面板">${icon('X')}</button></div><div class="modal-content">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!m.open)m.showModal()}
function closeModal(){document.getElementById('modal').close()}
function references(){modal('选择参考预设',`<p class="muted" style="margin-bottom:13px">选择用来借鉴格式与写法的预设。</p>${presets.filter(p=>p.id!==state.target).map(p=>`<label class="reference-option"><span class="reference-icon">${icon('FileText')}</span><span class="grow"><h3>${p.name}</h3><p>${p.meta}</p></span><input class="check" type="checkbox" value="${p.id}" name="ref" ${state.refs.includes(p.id)?'checked':''}></label>`).join('')}`,'<button class="btn primary" data-action="save-refs">使用所选参考</button>')}
function saveEditor(){const e=state.entries.find(e=>e.id===entryId);if(!e)return;const name=document.getElementById('edit-name').value.trim();if(!name){toast('请填写条目名称');return}checkpoint();e.name=name;e.content=document.getElementById('edit-content').value;e.role=document.getElementById('edit-role').value;e.position=document.getElementById('edit-position').value;e.depth=Math.max(0,Math.min(999,Number(document.getElementById('edit-depth').value)||0));e.group=document.getElementById('edit-group').value;save();entryId=null;render();toast('已保存到草稿')}
function requestDemo(text){text=text.trim();if(!text)return;if(text.length>2000){toast('演示输入请控制在 2000 字以内');return}checkpoint();state.messages.push({role:'user',content:text});const isWhale=/鲸|身份|头部|西瓜/.test(text);let plans=[];if(isWhale){const e=state.entries.find(e=>e.id==='identity')||state.entries[0];let name='大鲸鱼';const match=text.match(/改成[“「"]?([^，。\n”」"]{1,12})/);if(match)name=match[1].trim();plans=[{id:e.id,name:`${name} · 身份定义`,before:e.content,after:`你是${name}，一位沉稳、好奇的故事创作助手。\n用清楚、从容的语言回应，不堆砌海洋比喻。\n创作前先梳理情境与因果，再检查角色动机和信息边界。`,group:e.group,note:'身份与创作规划'}];state.messages.push({role:'assistant',content:`已准备“${name}”的身份与创作规划修改示例。你可以逐项审阅，也可以继续提出调整意见。`})}else{const init=state.entries.find(e=>e.id==='init');const output=state.entries.find(e=>e.id==='output');let setting=/古代|古风/.test(text)?'古代':/赛博/.test(text)?'赛博都市':/末日/.test(text)?'末日':'自定义';plans=[{id:'custom-world',name:`世界观 · ${setting}`,before:state.entries.find(e=>e.id==='custom-world')?.content||'',after:`{{setvar::custom_world::\n<worldview>\n背景：${setting}社会。\n权力与秩序：人物行动受身份、制度和地方习俗影响。\n信息与资源：遵循当前时代的交通、通信和生产条件。\n叙事要求：通过人物行动呈现规则，保持因果与角色信息边界。\n</worldview>\n}}\n{{trim}}`,group:'世界与叙事',note:'插入世界与叙事分组'}];if(init&&!init.content.includes('custom_world'))plans.push({id:init.id,name:init.name,before:init.content,after:init.content.replace('{{trim}}','{{setvar::custom_world::}}\n{{trim}}'),group:init.group,note:'补充变量初始化'});if(output&&!output.content.includes('custom_world'))plans.push({id:output.id,name:output.name,before:output.content,after:'{{getvar::custom_world}}\n'+output.content,group:output.group,note:'补充读取入口'});state.messages.push({role:'assistant',content:`已准备${setting}世界观的生成示例，并检查初始化和输出读取入口。建议放在“世界与叙事”分组，接受后才会加入草稿。`})}state.plans=plans;planSelection=new Set(plans.map((_,i)=>i));save();render();toast('演示建议已生成，等待你的审阅')}
function setQuery(value,id){search=value;const input=document.getElementById(id);const pos=input?.selectionStart;render();const next=document.getElementById(id);next?.focus();if(pos!=null)next?.setSelectionRange(pos,pos)}
document.addEventListener('input',e=>{if(e.target.id==='library-search'||e.target.id==='entry-search'||e.target.id==='knowledge-search')setQuery(e.target.value,e.target.id)});
document.addEventListener('change',e=>{if(e.target.dataset.select){e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);render()}if(e.target.dataset.plan!=null){const i=Number(e.target.dataset.plan);e.target.checked?planSelection.add(i):planSelection.delete(i);render()}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();requestDemo(document.getElementById('chat-input').value)}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action:a,value:v,id,index}=b.dataset;
 if(a==='nav')nav(v);
 else if(a==='tab'){entryId=null;search='';tab=v;route='work';location.hash='work';render();window.scrollTo(0,0)}
 else if(a==='filter'){filter=v;render()}
 else if(a==='close-modal')closeModal();
 else if(a==='toggle-ref'){if(id===state.target){toast('当前目标已作为编辑上下文，无需重复加入');return}state.refs=state.refs.includes(id)?state.refs.filter(x=>x!==id):[...state.refs,id];save();render()}
 else if(a==='open-preset'){if(id===state.target){nav('work');tab='edit';render()}else{const p=presets.find(x=>x.id===id);modal(p.name,`<div class="reference-option"><span class="reference-icon">${icon('FileText')}</span><span class="grow"><h3>世界观定义</h3><p>格式结构与变量写入</p></span></div><div class="diff-block after">{{setvar::worldview::\n&lt;worldview&gt;\n${p.name}的背景、规则与叙事边界。\n&lt;/worldview&gt;\n}}\n{{trim}}</div><p class="muted" style="margin-top:16px">这是参考预设的条目预览示例。</p>`,`<button class="btn primary" data-action="ref-and-chat" data-id="${id}">加入参考并创作</button>`)}}
 else if(a==='ref-and-chat'){if(!state.refs.includes(id))state.refs.push(id);save();closeModal();tab='ai';nav('work')}
 else if(a==='references')references();
 else if(a==='save-refs'){state.refs=[...document.querySelectorAll('input[name="ref"]:checked')].map(x=>x.value);save();closeModal();render();toast(`已选择 ${state.refs.length} 份参考`)}
 else if(a==='collapse'){state.collapsed=state.collapsed.includes(v)?state.collapsed.filter(x=>x!==v):[...state.collapsed,v];save();render()}
 else if(a==='bulk'){bulk=!bulk;selected.clear();render()}
 else if(a==='select-all'){selected=selected.size===state.entries.length?new Set():new Set(state.entries.map(x=>x.id));render()}
 else if(a==='edit-entry'){entryId=id;render();window.scrollTo(0,0)}
 else if(a==='toggle-entry'){checkpoint();const x=state.entries.find(x=>x.id===id);x.enabled=!x.enabled;save();render()}
 else if(a==='batch-toggle'){checkpoint();const enable=state.entries.some(x=>selected.has(x.id)&&!x.enabled);state.entries.filter(x=>selected.has(x.id)).forEach(x=>x.enabled=enable);save();render();toast(`已${enable?'启用':'停用'}所选条目，仅修改草稿`)}
 else if(a==='back-editor'){const x=state.entries.find(x=>x.id===entryId);if(x&&(document.getElementById('edit-content').value!==x.content||document.getElementById('edit-name').value!==x.name)){modal('保留这次编辑？','<p class="muted">当前内容尚未保存到草稿。</p>','<button class="btn" data-action="discard-editor">放弃修改</button><button class="btn primary" data-action="save-and-close-editor">保存到草稿</button>')}else{entryId=null;render()}}
 else if(a==='discard-editor'){entryId=null;closeModal();render()}
 else if(a==='save-and-close-editor'){closeModal();saveEditor()}
 else if(a==='save-entry')saveEditor();
 else if(a==='reference-entry'){entryId=null;tab='ai';render();document.getElementById('chat-input').value=`请修改“${state.entries.find(x=>x.id===id)?.name}”：`;document.getElementById('chat-input').focus()}
 else if(a==='undo'){if(history.length){state=history.pop();save();render();toast('已撤销上一步草稿修改')}}
 else if(a==='quick-prompt')requestDemo(v);
 else if(a==='apply-plans'){if(!planSelection.size){toast('至少选择一处修改');return}checkpoint();state.plans.filter((p,i)=>planSelection.has(i)).forEach(p=>{let x=state.entries.find(x=>x.id===p.id);if(x){x.name=p.name;x.content=p.after}else{const entry={id:p.id,name:p.name,group:p.group,content:p.after,enabled:true,role:'system',depth:4,position:'relative'};const anchor=state.entries.findIndex(x=>x.group===p.group);state.entries.splice(anchor<0?state.entries.length:anchor+1,0,entry)}});state.plans=state.plans.filter((p,i)=>!planSelection.has(i));planSelection=new Set(state.plans.map((_,i)=>i));save();render();toast('所选修改已加入草稿')}
 else if(a==='discard-plans'){state.plans=[];planSelection.clear();save();render();toast('已放弃建议，保留现有草稿')}
 else if(a==='save-version'){state.baseline=clone(state.entries);state.lastSaved=Date.now();save();render();toast('演示版本已保存在当前浏览器')}
 else if(a==='revert'){modal('恢复已保存版本？','<p class="muted">将放弃当前草稿的修改。你仍可以撤销这一步。</p>','<button class="btn" data-action="close-modal">继续编辑</button><button class="btn primary" data-action="confirm-revert">恢复版本</button>')}
 else if(a==='confirm-revert'){checkpoint();state.entries=clone(state.baseline);save();closeModal();render();toast('已恢复已保存版本')}
 else if(a==='move'){modal('移动所选条目',`<p class="muted" style="margin-bottom:15px">${selected.size} 个条目保持原有相对顺序。</p><label class="field"><span class="field-label">移到</span><select id="move-anchor" style="width:100%"><option value="top">列表顶部</option><option value="bottom">列表底部</option>${state.entries.filter(x=>!selected.has(x.id)).map(x=>`<option value="${x.id}">${esc(x.name)}之前</option>`).join('')}</select></label>`,'<button class="btn primary" data-action="confirm-move">移动到这里</button>')}
 else if(a==='confirm-move'){checkpoint();const anchor=document.getElementById('move-anchor').value,items=state.entries.filter(x=>selected.has(x.id)),rest=state.entries.filter(x=>!selected.has(x.id));let idx=anchor==='top'?0:anchor==='bottom'?rest.length:rest.findIndex(x=>x.id===anchor);if(idx<0)idx=rest.length;const targetGroup=anchor==='top'?rest[0]?.group:anchor==='bottom'?rest.at(-1)?.group:rest[idx]?.group;items.forEach(x=>{if(targetGroup)x.group=targetGroup});rest.splice(idx,0,...items);state.entries=rest;state.collapsed=[];save();closeModal();render();toast('已移动所选条目，仅修改草稿')}
 else if(a==='add-entry'){checkpoint();const x={id:'entry-'+Date.now(),name:'新条目',group:'写作约束',content:'',enabled:true,role:'system',depth:4,position:'relative'};state.entries.push(x);entryId=x.id;save();render()}
 else if(a==='new'){modal('开始一份新预设','<label class="field"><span class="field-label">预设名称</span><input id="new-preset-name" style="width:100%" placeholder="例如：雨夜故事集"></label><p class="muted">原型将用演示结构创建一个新的编辑目标。</p>','<button class="btn primary" data-action="confirm-new">创建演示草稿</button>')}
 else if(a==='confirm-new'){const n=document.getElementById('new-preset-name').value.trim();if(!n){toast('请填写名称');return}checkpoint();state.targetName=n;state.entries=clone(seeds.slice(0,7));state.baseline=clone(state.entries);state.plans=[];state.messages=[];save();closeModal();tab='edit';nav('work')}
 else if(a==='import'){modal('导入预设','<p class="muted">正式版本支持导入酒馆 JSON，并保留原始字段。本原型暂用内置示例预设演示操作。</p><div class="small-spacer"></div><button class="btn full" data-action="close-modal">继续使用示例</button>')}
 else if(a==='settings'){modal('工作台设置',`<label class="field"><span class="field-label">按编号插入时默认放在</span><select id="default-insert-side"><option value="before" ${state.insertSide==='before'?'selected':''}>目标条目之前</option><option value="after" ${state.insertSide!=='before'?'selected':''}>目标条目之后</option></select></label>`,'<button class="btn danger" data-action="reset-confirm">重置当前草稿</button><button class="btn primary" data-action="close-modal">完成</button>')}
 else if(a==='reset-confirm'){modal('重置演示数据？','<p class="muted">清除当前浏览器中的演示修改，恢复初始预设。</p>','<button class="btn" data-action="close-modal">取消</button><button class="btn danger" data-action="reset">确认重置</button>')}
 else if(a==='reset'){try{localStorage.removeItem(KEY)}catch{}location.reload()}
 else if(a==='knowledge-toggle'){state.knowledgeOn[Number(index)]=!state.knowledgeOn[Number(index)];save();render()}
 else if(a==='new-knowledge'){modal('添加一条经验','<label class="field"><span class="field-label">经验内容</span><textarea id="new-knowledge" style="width:100%;min-height:140px" placeholder="记录适用模型、版本、观察与来源"></textarea></label><p class="muted">本次仅预览编辑面板，暂不写入经验库。</p>','<button class="btn primary" data-action="close-modal">返回经验库</button>')}
 else if(a==='run-test'){const view=state.entries.find(x=>x.id==='custom-world');document.getElementById('test-result').innerHTML=`<div class="comparison"><div class="sample"><h3>已保存版本</h3>“从哪里来？”守城人抬头问。她收起湿透的伞，朝身后的长街看了一眼。</div><div class="sample"><h3>当前草稿</h3>${view?'城门将闭。她取出路引，守卒借灯火验过籍贯，才将木栅推开半尺。':'“从哪里来？”守城人抬头问。她收起湿透的伞，朝身后的长街看了一眼。'}</div></div><p class="muted">预先编写的演示文本，未发起模型请求。</p>`}
 else if(a==='upgrade'){modal('预设升级 · 三方比较','<p class="muted">正式版本将同时载入三份内容，逐项确认合并。</p><div class="radio-card">作者旧版 <span class="muted" style="margin-left:auto">比较基线</span></div><div class="radio-card">你的修改版 <span class="muted" style="margin-left:auto">保留个人改动</span></div><div class="radio-card">作者新版 <span class="muted" style="margin-left:auto">合入作者更新</span></div><p class="muted" style="margin-top:15px">此处为页面结构预览，尚未实现合并算法。</p>','<button class="btn primary" data-action="close-modal">返回实验室</button>')}
});
document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'library';if(next!==route){route=next;entryId=null;search='';render()}});
hydrateIcons();render();
